Embedding `component.Host` only promotes `GetExtensions`. Any other optional capability of the service host is hidden from extensions, except `RegisterZPages`, which is forwarded explicitly. Extensions that use type assertions for `hostcapabilities.ComponentFactory` (`GetFactory`) or `hostcapabilities.ModuleInfo` (`GetModuleInfos`) would stop working, which is a user-visible regression. Forward these capabilities to the wrapped host as well.

Improved code:
func (host *hostWrapper) RegisterZPages(mux *http.ServeMux, pathPrefix string) {
	if hostZPages, ok := host.Host.(interface {
		RegisterZPages(mux *http.ServeMux, pathPrefix string)
	}); ok {
		hostZPages.RegisterZPages(mux, pathPrefix)
	}
}

// GetFactory forwards to the underlying host so extensions keep access to component factories.
func (host *hostWrapper) GetFactory(kind component.Kind, componentType component.Type) component.Factory {
	if f, ok := host.Host.(interface {
		GetFactory(kind component.Kind, componentType component.Type) component.Factory
	}); ok {
		return f.GetFactory(kind, componentType)
	}
	return nil
}

// GetModuleInfos forwards to the underlying host so extensions keep access to module information.
func (host *hostWrapper) GetModuleInfos() moduleinfo.ModuleInfos {
	if mi, ok := host.Host.(interface {
		GetModuleInfos() moduleinfo.ModuleInfos
	}); ok {
		return mi.GetModuleInfos()
	}
	return moduleinfo.ModuleInfos{}
}

`hostWrapper` embeds only the `component.Host` interface, so any optional interfaces the underlying host implements (e.g. `componentstatus.Reporter`-adjacent or other extension-facing interfaces such as `GetExtensions`/`GetFactory`-style helpers) are silently hidden from extensions. Only `RegisterZPages` is forwarded. Consider whether other optional interfaces extensions rely on need forwarding, otherwise type assertions on the wrapped host will now fail and break existing extensions.

Improved code:
func (host *hostWrapper) RegisterZPages(mux *http.ServeMux, pathPrefix string) {
	if hostZPages, ok := host.Host.(interface {
		RegisterZPages(mux *http.ServeMux, pathPrefix string)
	}); ok {
		hostZPages.RegisterZPages(mux, pathPrefix)
	}
}

// Unwrap returns the underlying host so extensions can discover optional
// interfaces implemented by the original host.
func (host *hostWrapper) Unwrap() component.Host {
	return host.Host
}

The wrapper only forwards `RegisterZPages`, so any other optional interface the real host implements (for example `GetExtensions`, `GetFactory`) is hidden from extensions after wrapping. Extensions that type-assert on the host will silently stop working. Forward the other optional host methods, or avoid wrapping when no status reporting is needed.

Improved code:
func (host *hostWrapper) RegisterZPages(mux *http.ServeMux, pathPrefix string) {
	if hostZPages, ok := host.Host.(interface {
		RegisterZPages(mux *http.ServeMux, pathPrefix string)
	}); ok {
		hostZPages.RegisterZPages(mux, pathPrefix)
	}
}

// GetExtensions forwards to the wrapped host when it supports it, preserving
// optional-interface discovery for extensions.
func (host *hostWrapper) GetExtensions() map[component.ID]component.Component {
	if h, ok := host.Host.(interface {
		GetExtensions() map[component.ID]component.Component
	}); ok {
		return h.GetExtensions()
	}
	return nil
